import { focus } from "../../helpers";
import { Button, buttonVariant } from "../Button";
import { StyleFn } from "..";

export const Tabs: StyleFn = () => ({
  root: {
    // reset
    margin: 0,
    padding: 0,
    listStyleType: "none",
    // layout
    display: "inline-flex",
    whiteSpace: "nowrap",
    marginBottom: "1px",
    // workaround for no bottom border on child tabs
    "&$_floating [role=tab]:not(:focus-visible):before": {
      borderBottom: "none",
    },
    "&$_floating [role=tab]:after": {
      borderWidth: 2,
    },
  },
  _floating: {
    marginBottom: 0,
    // floating tabs stretch to full height
    alignSelf: "stretch",
  },
  scrollwrapper: {
    display: "flex",
    alignSelf: "stretch",
    overflow: "hidden",
    maskImage: "linear-gradient(to right, black 95%, transparent 100%)",
    "& $root": {
      overflow: "hidden",
      overflowX: "scroll",
      flex: "1 1 auto",
      scrollbarWidth: "none",
      "&::-webkit-scrollbar": {
        display: "none",
      },
    },
  },
});

export const Tab: StyleFn = (theme, mode) => {
  const { color, font, size, opacity } = theme;
  const {
    root: rootButtonStyles,
    _medium,
    _large,
    _xlarge,
  } = Button(theme, mode);
  const { focusWithPseudo } = focus(theme, mode);
  const borderColor = color.border.accent.default[mode];
  // FIX: The color is set conditionally for dark mode as a workaround for a global theme CSS selector:[data-theme=dark]
  const containerHoverBgColor =
    mode === "dark"
      ? color.surface.componentonbackground.moderate.dark
      : color.surface.componentonbackground.moderate.light;

  return {
    root: {
      extend: [
        rootButtonStyles,
        buttonVariant(theme, mode, "ghost"),
        focusWithPseudo({
          pseudo: "before",
          radius: "0",
          offset: 0,
          borderWidth: "4px",
          transparentBorder: false,
        }),
      ],
      borderRadius: 0,
      color: color.text.accent.corporate[mode],
      display: "inline-flex",
      minWidth: "initial",
      fontWeight: font.weight.medium,
      height: "100%",
      position: "relative",
      padding: `${size.spacing[8]} ${size.spacing[16]}`,
      "&:before": {
        content: '""',
        position: "absolute",
        left: 0,
        right: 0,
        bottom: 0,
        borderBottom: `1px solid ${color.border.accent.corporate[mode]}`,
      },
      "&:hover": {
        backgroundColor: color.surface.interaction.hover[mode],
      },
    },
    _negative: {
      "&:before": {
        borderBottom: `1px solid ${color.border.neutral.white[mode]}`,
      },
      // increased specificity to override [data-theme=dark] styles
      "&$_negative&": {
        color: color.text.white[mode],
        "&:focus-visible:before": {
          borderColor: color.border.neutral.white[mode],
        },
        "&:hover": {
          backgroundColor: color.surface.interaction.transparenthover[mode],
        },
        "&:active": {
          backgroundColor: color.surface.interaction.transparentactive[mode],
        },
        "&$_selected": {
          backgroundColor: color.surface.interaction.transparentactive[mode],
          "&:hover": {
            backgroundColor: color.surface.interaction.transparentactive[mode],
          },
          "&:after": {
            borderColor: color.palette.primaryblue[40],
          },
        },
      },
    },
    _medium,
    _large,
    _xlarge,
    _container: {
      backgroundColor: color.surface.componentonbackground.minimal[mode],
      "&:before": {
        borderColor: color.border.neutral.moderate[mode],
        bottom: 0,
      },
      "&:hover": {
        backgroundColor: containerHoverBgColor,
      },
      "&$_selected": {
        backgroundColor: color.surface.elevation[6][mode],
        "&:hover": {
          backgroundColor: containerHoverBgColor,
        },
        "&:before": { display: "none" },
        "&:focus-visible:before": { display: "block" },
        "&:after": {
          top: 0,
          right: 0,
          left: 0,
          bottom: "unset",
        },
      },
    },
    _selected: {
      fontWeight: font.weight.bold,
      "&:after": {
        content: '""',
        position: "absolute",
        left: 0,
        right: 0,
        bottom: 0,
        zIndex: 1,
        border: `2px solid ${borderColor}`,
      },
      "&:hover": {
        cursor: "unset",
      },
    },
    _disabled: {
      pointerEvents: "none",
      opacity: opacity.disabled,
    },
  };
};
